import { defineEventHandler, proxyRequest, getHeader, getRequestURL, getHeaders, createError } from "h3";
import { buildValidatedProxyUrl } from "../../utils/proxy-target";

export default defineEventHandler(async (event) => {
  const targetBaseUrl = getHeader(event, "x-target-url");

  if (!targetBaseUrl) {
    throw createError({
      statusCode: 400,
      statusMessage: "Missing x-target-url header",
    });
  }

  const reqUrl = getRequestURL(event);
  const proxyPath = reqUrl.pathname.replace(/^\/api\/chat-proxy\/?/, "") + reqUrl.search;
  let fullTargetUrl: string;
  try {
    fullTargetUrl = buildValidatedProxyUrl(targetBaseUrl, proxyPath, {
      allowHttp: process.dev || import.meta.env?.DEV,
      allowLocal: process.dev || import.meta.env?.DEV,
    });
  } catch (err) {
    throw createError({
      statusCode: 400,
      statusMessage: err instanceof Error ? err.message : "Invalid proxy target",
    });
  }

  const forbiddenHeaders = [
    "x-stainless-os",
    "x-stainless-lang",
    "x-stainless-package-version",
    "x-stainless-runtime",
    "x-stainless-runtime-version",
    "x-stainless-arch",
    "x-stainless-os-version",
    "origin",
    "host",
    "referer",
    "x-target-url",
  ];

  const headers: Record<string, string> = { ...getHeaders(event) };
  for (const forbidden of forbiddenHeaders) {
    delete headers[forbidden];
  }

  if (process.dev || import.meta.env?.DEV) {
    const hasAuth = !!headers["authorization"];
    const hasApiKey = !!headers["x-api-key"];
    console.log(`[chat-proxy] ${event.method} ${proxyPath} -> ${new URL(fullTargetUrl).hostname} (auth=${hasAuth}, xApiKey=${hasApiKey})`);
  }

  return proxyRequest(event, fullTargetUrl, {
    headers,
  });
});
export interface ProxyTargetValidationOptions {
	allowHttp?: boolean;
	allowLocal?: boolean;
}

function normalizeHostname(hostname: string): string {
	return hostname.toLowerCase().replace(/^\[|\]$/g, "").replace(/\.$/, "");
}

function parseIPv4(hostname: string): number[] | null {
	const parts = hostname.split(".");
	if (parts.length !== 4) return null;
	const octets = parts.map((part) => {
		if (!/^\d+$/.test(part)) return Number.NaN;
		const value = Number(part);
		return value >= 0 && value <= 255 ? value : Number.NaN;
	});
	return octets.every(Number.isFinite) ? octets : null;
}

function isPrivateIPv4(octets: number[]): boolean {
	const [a, b, c] = octets;
	return (
		a === 0 ||
		a === 10 ||
		a === 127 ||
		(a === 100 && b >= 64 && b <= 127) ||
		(a === 169 && b === 254) ||
		(a === 172 && b >= 16 && b <= 31) ||
		(a === 192 && b === 168) ||
		(a === 192 && b === 0 && c === 0) ||
		(a === 198 && (b === 18 || b === 19)) ||
		a >= 224
	);
}

function isPrivateIPv6(hostname: string): boolean {
	const host = normalizeHostname(hostname);
	if (!host.includes(":")) return false;
	if (host === "::" || host === "::1") return true;
	if (host.startsWith("fc") || host.startsWith("fd") || host.startsWith("fe80") || host.startsWith("fec0")) return true;
	if (host.startsWith("ff")) return true;
	const mappedIPv4 = host.match(/(?:::ffff:)?(\d+\.\d+\.\d+\.\d+)$/)?.[1];
	if (mappedIPv4) {
		const octets = parseIPv4(mappedIPv4);
		return octets ? isPrivateIPv4(octets) : false;
	}
	return false;
}

export function isLocalOrPrivateHostname(hostname: string): boolean {
	const host = normalizeHostname(hostname);
	if (
		host === "localhost" ||
		host.endsWith(".localhost") ||
		host.endsWith(".local") ||
		host.endsWith(".internal") ||
		host.endsWith(".lan")
	) {
		return true;
	}
	const ipv4 = parseIPv4(host);
	if (ipv4) return isPrivateIPv4(ipv4);
	return isPrivateIPv6(host);
}

export function validateProxyTargetBaseUrl(
	value: string,
	options: ProxyTargetValidationOptions = {},
): URL {
	const raw = value.trim();
	if (!raw) throw new Error("Missing x-target-url header");

	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		throw new Error("Invalid x-target-url header");
	}

	if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
		throw new Error("Proxy target must use http or https");
	}
	if (parsed.protocol === "http:" && !options.allowHttp) {
		throw new Error("Proxy target must use https");
