			if (done) return;
			done = true;
			session?.close();
			reject(new Error("Gemini Live speech timed out."));
		}, 30_000);

		const abort = () => {
			if (done) return;
			done = true;
			clearTimeout(timeout);
			session?.close();
			reject(new Error("Gemini Live speech aborted."));
