						reject(new Error(event.message || "Gemini Live speech failed."));
					},
					onclose: () => {
						if (done) return;
						clearTimeout(timeout);
						signal?.removeEventListener("abort", abort);
						finish(resolve);
					},
				},
				config: {
					responseModalities: [Modality.AUDIO],
					outputAudioTranscription: {},
					speechConfig: {
						voiceConfig: {
							prebuiltVoiceConfig: { voiceName: utterance.voice },
						},
					},
					systemInstruction:
						"You are Keating's voice layer. Speak the provided learner-facing line only. Keep it natural, concise, and conversational. Do not add extra teaching content.",
					thinkingConfig: { thinkingLevel: ThinkingLevel.MINIMAL },
				},
			}), { signal })
			.then((liveSession) => {
				if (done) {
					liveSession.close();
					return;
				}
				session = liveSession;
				session.sendRealtimeInput({
					text: `${voiceTagLine(utte…2027 tokens truncated…* 0.25);
		const topQuartile = sorted[qIdx]?.score ?? sorted[0]?.score ?? 0;
		return { count: sorted.length, avgScore, avgWeightedScore: avgWeighted, topQuartile };
	}

	// Evolutions
	async saveEvolution(bestScore: number, policy: string, report: string, topic?: string, trace?: string): Promise<EvolutionResult> {
		const evolution: EvolutionResult = {
			id: this.generateId(),
			topic,
